generated_qss:
QMainWindow, QWidget { background-color: #1A1D23; color: #CDD6F4; font-size: 10pt; }

QGroupBox {
    border: 1px solid #313244;
    border-radius: 4px;
    margin-top: 8px;
    padding-top: 0px;
    font-weight: bold;
    color: #89B4FA;
}
QGroupBox::title {
    subcontrol-origin: margin;
    left: 8px;
    padding: 0 4px;
}

QTabWidget::pane
{
    border: 1px solid #313244;
    top: -1px;
}

QTabBar::tab
{
    background-color: #1E2128;
    color: #CDD6F4;
    padding: 6px 12px;
    border: 1px solid #313244;
    border-top-left-radius: 4px;
    border-top-right-radius: 4px;
    min-width: 70px;
}

QTabBar::tab:selected
{
    background-color: #262A33;
    color: #89B4FA;
    font-weight: 600;
    margin-bottom: 0px;
}

QTabBar::tab:hover
{
    background-color: #89B4FA;
    color: #1A1D23;
}

QTabBar::tab:!selected
{
    margin-top: 2px;
}

QListWidget { background-color: #1E2128; }
QListWidget::item:selected { background-color: #89B4FA; color: #1A1D23; }

QTableView {
    background-color: #1E2128;
    alternate-background-color: #1A1D23;
    color: #CDD6F4;
    gridline-color: #313244;
    selection-background-color: #262A33;
}
QHeaderView::section {
    background-color: #262A33;
    color: #89B4FA;
    border: 1px solid #313244;
    padding: 3px;
    font-weight: bold;
}
QTableWidget {
    background-color: #1E2128;
    color: #CDD6F4;
    gridline-color: #313244;
}

/* ---- Global input sizing ---------------------------------------------- */
QLineEdit, QComboBox, QSpinBox, QDoubleSpinBox, QDateEdit, QTimeEdit,
QDateTimeEdit, QPlainTextEdit, QAbstractSpinBox {
    background-color: #262A33;
    color: #CDD6F4;
    border: 1px solid #313244;
    border-radius: 3px;
    min-height: 28px;
    padding-top: 4px;
    padding-bottom: 4px;
    padding-left: 4px;
    padding-right: 4px;
}
QComboBox QAbstractItemView {
    background: #262A33;
    color: #CDD6F4;
    selection-background-color: #89B4FA;
    selection-color: #1A1D23;
}
QComboBox QAbstractItemView::item { min-height: 28px; }
QComboBox::drop-down { border: none; min-height: 28px; }

QTextEdit {
    background-color: #1E2128;
    color: #CDD6F4;
    border: 1px solid #313244;
}

QPushButton {
    background-color: #262A33;
    color: #CDD6F4;
    border: 1px solid #313244;
    border-radius: 4px;
    padding: 5px 10px;
}
QPushButton:hover { background-color: #89B4FA; color: #1A1D23; }
QPushButton:disabled { color: #9399B2; border-color: #313244; }

/* ---- Named action buttons (set via objectName) ------------------------ */
QPushButton#btnConnect    { background-color: #40A02B;     color: #11111B; font-weight: bold; }
QPushButton#btnDisconnect { background-color: #E64553;  color: #11111B; }
QPushButton#btnRead       { background-color: #40A02B;        color: #11111B; font-weight: bold; }
QPushButton#btnWrite      { background-color: #1E66F5;       color: #11111B; font-weight: bold; }
QPushButton#btnWriteRead  { background-color: #8839EF;  color: #11111B; font-weight: bold; }
QPushButton#btnScan       { background-color: #FE640B;        color: #11111B; font-weight: bold; }
QPushButton#btnApply      { font-weight: bold; }
QPushButton#btnSpyStart   { background-color: #40A02B;     color: #11111B; font-weight: bold; font-size: 13px; padding: 6px; }
QPushButton#btnSpyStop    { background-color: #E64553;  color: #11111B; font-weight: bold; font-size: 13px; padding: 6px; }

QLabel#specgenSectionHeading {
    font-size: 13pt;
    font-weight: 600;
    color: #CDD6F4;
    margin-top: 8px;
    margin-bottom: 4px;
}

QLabel#noteLabel { color: #DF8E1D; font-size: 10px; }
QLabel#mutedLabel { color: #9399B2; }
/* [XREF: file-picker] validated file-status line colors */
QLabel#statusOk { color: #40A02B; }
QLabel#statusError { color: #E64553; }

QPushButton[saveDirty="true"] {
    background-color: #40A02B;
    color: #11111B;
    font-weight: 600;
    border-radius: 3px;
    padding: 4px 12px;
}
QPushButton[saveDirty="true"]:hover { background-color: #4CB535; }

QStatusBar { background-color: #262A33; color: #CDD6F4; }
QSplitter::handle { background: #313244; }
QScrollBar:vertical { background: #1A1D23; width: 10px; }
QScrollBar::handle:vertical { background: #313244; border-radius: 4px; min-height: 20px; }
QCheckBox { color: #CDD6F4; spacing: 5px; }
QRadioButton { color: #CDD6F4; spacing: 6px; }
QProgressDialog { background-color: #1A1D23; color: #CDD6F4; }
